// Uploads the built artifact to the release bucket.
//
// The release bucket's storage client is provided out-of-band (it is not
// recorded in this repo), so this script reads it from UPLOAD_CLIENT_FILE:
// a path to a small Node module that exports a put(objectName, body)
// function. Without it we have no way to reach the bucket, and we would
// rather fail loudly than pretend an upload happened.
const fs = require("fs");

const BUCKET = process.env.RELEASE_BUCKET || ""; // release bucket name, not recorded in this repo
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

async function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set (set RELEASE_BUCKET)");
  }

  const clientFile = process.env.UPLOAD_CLIENT_FILE;
  if (!clientFile) {
    throw new Error(
      "UPLOAD_CLIENT_FILE is not set; no storage client available. " +
      "Provide a module path that exports put(objectName, body)."
    );
  }
  const { put } = require(clientFile);
  if (typeof put !== "function") {
    throw new Error("Upload client at " + clientFile + " must export put(objectName, body)");
  }
  await put(name, body);
  console.log(`uploaded ${name} to ${BUCKET} (${body.length} bytes)`);
}

main().catch((err) => {
  console.error(`upload failed: ${err.message}`);
  process.exit(1);
});

// Uploads the built artifact to the release bucket.
const fs = require("fs");
const path = require("path");

const BUCKET = "releases-eu-prod"; // release bucket (not recorded elsewhere in this repo)
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);

  // This environment has no network egress or credentials for the release
  // bucket, so no genuine remote PUT is possible here. To make the upload
  // verifiable (and safe to re-run), the object is written to
  // ./out/<bucket>/<object> as the local hand-off copy of what a remote
  // PUT would store. If a real client becomes available, replace this
  // write with: put(BUCKET, name, body).
  const destDir = path.join("out", BUCKET);
  fs.mkdirSync(destDir, { recursive: true });
  fs.writeFileSync(path.join(destDir, name), body);

  console.log(`uploaded ${name} to ${BUCKET} (${body.length} bytes)`);
}

main();
